from app.db import execute, TransientConnectionError, primary_dsn
from app.settings import load_settings

settings = load_settings()
assert settings["db"]["reconnect_attempts"] == 3
assert "primary" in settings["db"]
print("settings ok", settings["db"]["reconnect_attempts"], primary_dsn(settings))

class Conn:
    def __init__(self, fail_n, counter):
        self.fail_n = fail_n
        self.counter = counter
    def run(self, op):
        self.counter["n"] += 1
        if self.counter["n"] <= self.fail_n:
            raise TransientConnectionError("drop")
        return f"row-{op['id']}"

# succeeds on 3rd attempt (2 failures)
counter = {"n": 0}
def connect(dsn):
    assert dsn == settings["db"]["primary"]
    return Conn(2, counter)
row = execute({"id": "a"}, connect, settings)
assert row == "row-a" and counter["n"] == 3
print("retry success ok")

# exhausts budget
counter = {"n": 0}
def connect2(dsn):
    return Conn(5, counter)
try:
    execute({"id": "b"}, connect2, settings)
    assert False, "should raise"
except TransientConnectionError:
    assert counter["n"] == 3
    print("budget exhausted ok")

# non-transient does not retry
class Boom(Exception):
    pass
calls = {"n": 0}
class Bad:
    def run(self, op):
        calls["n"] += 1
        raise Boom("nope")
def connect3(dsn):
    return Bad()
try:
    execute({"id": "c"}, connect3, settings)
    assert False
except Boom:
    assert calls["n"] == 1
    print("non-transient ok")

# writer path
from app.writer import record_batch
class Mixed:
    def __init__(self):
        self.n = 0
    def run(self, op):
        self.n += 1
        if op["id"] == "fail":
            raise TransientConnectionError("x")
        if op["id"] == "retry" and self.n < 2:
            raise TransientConnectionError("x")
        return f"row-{op['id']}"
m = Mixed()
def connect4(dsn):
    return m
# need separate counters per op - reset between ops via new Mixed per connect? 
# actually Mixed shares state across ops which is fine for this rough test if we structure carefully

class Flaky:
    def __init__(self, fails_left):
        self.fails_left = fails_left
    def run(self, op):
        if self.fails_left > 0:
            self.fails_left -= 1
            raise TransientConnectionError("drop")
        return f"row-{op['id']}"

state = {"retry": 1, "ok": 0, "fail": 99}
def connect5(dsn):
    # each connection attempt gets its own conn with remaining fails from state
    op_id = connect5.current
    # can't know op here - use sequential ops differently
    return None

# simpler: track by connect call count per op via sequential processing
class Seq:
    def __init__(self):
        self.by_op = {"retry": 0, "ok": 0, "fail": 0}
        self.current = None
    def connect(self, dsn):
        op = self.current
        class C:
            def run(inner, o):
                self.by_op[o["id"]] += 1
                if o["id"] == "retry" and self.by_op[o["id"]] < 2:
                    raise TransientConnectionError("d")
                if o["id"] == "fail":
                    raise TransientConnectionError("d")
                return f"row-{o['id']}"
        return C()

s = Seq()
def connect6(dsn):
    return s.connect(dsn)

# record_batch calls execute which doesn't tell connect the op before connect...
# We need connect to return conn that decides based on op in run().
class Seq2:
    def __init__(self):
        self.counts = {}
    def __call__(self, dsn):
        outer = self
        class C:
            def run(self, op):
                i = outer.counts.get(op["id"], 0) + 1
                outer.counts[op["id"]] = i
                if op["id"] == "retry" and i < 2:
                    raise TransientConnectionError("d")
                if op["id"] == "fail":
                    raise TransientConnectionError("d")
                return f"row-{op['id']}"
        return C()

connect7 = Seq2()
out = record_batch([
    {"id": "ok"},
    {"id": "retry"},
    {"id": "fail"},
], connect7, settings)
print(out)
assert out[0] == {"id": "ok", "outcome": "committed", "row": "row-ok"}
assert out[1] == {"id": "retry", "outcome": "committed", "row": "row-retry"}
assert out[2]["outcome"] == "failed" and out[2]["error"] == "TransientConnectionError"
assert connect7.counts == {"ok": 1, "retry": 2, "fail": 3}
print("record_batch ok")
